  // callback in the unregistered raw worker. Decode only after its pinned
  // kernel observations have returned to the normal caller thread.
  raw_metadata_owner::Snapshot snapshot{};
  if (raw_metadata_owner::Read(fd, &snapshot) < 0) return -1;
  request->lookup = Lookup::kOrdinary;
  if (snapshot.tagged) {
    const auto& config = *request->config;
    if (config.initial_userns_device != kTrustedUserNamespaceDevice ||
        config.initial_userns_inode != kTrustedUserNamespaceInode) return Error(EINVAL);
    if (!DecodeOrigin(snapshot.tag, snapshot.tag_size, &request->origin)) return Error(EBADMSG);
    if (request->origin.words[kFactoryUsernsDevice] != config.initial_userns_device ||
        request->origin.words[kFactoryUsernsInode] != config.initial_userns_inode ||
        request->origin.words[kBackingDevice] != static_cast<uint64_t>(snapshot.identity.st_dev) ||
        request->origin.words[kBackingInode] != static_cast<uint64_t>(snapshot.identity.st_ino) ||
        request->origin.words[kBackingSize] != static_cast<uint64_t>(snapshot.identity.st_size)) {
      return Error(ESTALE);
    }
    request->lookup = Lookup::kVirtual;
  }
  switch (request->operation) {
    case MetadataOperation::kOrigin:
      return 0;
    case MetadataOperation::kStat:
      if (request->lookup == Lookup::kOrdinary) {request->info = snapshot.identity; return 0;}
      if (!DecodeStat(request->origin, &request->info)) return Error(EBADMSG);
      return 0;
    case MetadataOperation::kStatfs:
      if (request->lookup == Lookup::kOrdinary) {request->filesystem = snapshot.filesystem; return 0;}
      if (!DecodeStatfs(request->origin, &request->filesystem)) return Error(EBADMSG);
      return 0;
    case MetadataOperation::kKernelStatfs:
      if (request->lookup == Lookup::kOrdinary) {
